const FALLBACK = "Public read failed: could not read the Robinhood mainnet head.";

/** Only expose recognized diagnostics generated by the public reader itself. */
export function formatPublicReadFailure(error: unknown): string {
  if (!(error instanceof Error)) return FALLBACK;
  const message = error.message;
  const http = /^(Chain directory request|Public RPC eth_chainId|Public RPC eth_blockNumber) failed \(HTTP ([1-5][0-9]{2})\)$/.exec(message);
  if (http && http[0] === message) {
    const phase = http[1] === "Chain directory request" ? "Chain directory" : http[1];
    const hint = http[2] === "429"
      ? "Wait before trying again manually; this command does not retry."
      : "Check service availability before trying again manually; this command does not retry.";
    return `Public read failed: ${phase} returned HTTP ${http[2]}. ${hint}`;
  }
  const timeout = /^(Chain directory|Public RPC eth_chainId|Public RPC eth_blockNumber) (request|response) timed out$/.exec(message);
  if (timeout && timeout[0] === message) {
    return `Public read failed: ${timeout[1]} ${timeout[2]} timed out. Check connectivity and service availability before trying again manually; this command does not retry.`;
  }
  return FALLBACK;
}
